mapper.sql:
and not exists (
    select 1 from t_ticket t
    where t.train_id = s.train_id
      and t.carriage_number = s.carriage_number
      and t.seat_number = s.seat_number
      and t.ticket_status in (0, 1, 2)
      and t.del_flag = 0
      and t.departure < #{arrival}
      and t.arrival > #{departure}
)

mapper.select:
select s.carriage_number as carriageNumber, count(*) as seatCount from t_seat s where s.train_id = #{trainId} and s.del_flag = 0 and s.carriage_number in
#{carriage}
group by s.carriage_number

select s.seat_type as seatType, count(*) as seatCount from t_seat s where s.train_id = #{trainId} and s.del_flag = 0 and s.seat_type in
#{seatType}
and not exists ( select 1 from t_ticket t where t.train_id = s.train_id and t.carriage_number = s.carriage_number and t.seat_number = s.seat_number and t.ticket_status in (0, 1, 2) and t.del_flag = 0 and t.departure < #{endStation} and t.arrival > #{startStation} ) group by s.seat_type having seatCount > 0

select s.seat_number
from t_seat s
where s.train_id = #{trainId}
and s.carriage_number = #{carriageNumber}
and s.seat_type = #{seatType}
and s.del_flag = 0

order by s.seat_number
